// Drag-to-reorder motion for the Browser tab strip.
//
// Injected after the base Browser template and before the dark-theme overrides
// so light and dark themes share the same motion contract. The values are part
// of that contract: grab 120 ms ease-out (the source only fades — it is NEVER
// repositioned, because Chromium cancels a native drag when the drag source
// leaves its layout position), neighbour yield and drop settle 150 ms
// cubic-bezier(0.2, 0, 0, 1), and every transition disabled under
// prefers-reduced-motion (the rest position stays exact). There is no
// insertion line: the neighbours' yielding is the insertion-point expression.
// Shape language stays flat: the dragged tab deepens its border to the accent
// token; no shadow or glow is added.
export const BROWSER_TAB_DRAG_CSS = `
      .browser-tabstrip-tabs {
        position: relative;
      }
      .browser-tab {
        transition: transform 150ms cubic-bezier(0.2, 0, 0, 1), opacity 120ms ease-out, border-color 120ms ease-out;
      }
      .browser-tab.is-dragging {
        transform: scale(1.02) translateY(-1px);
        opacity: .05;
        border-color: var(--browser-accent);
        transition: transform 120ms ease-out, opacity 120ms ease-out, border-color 120ms ease-out;
        z-index: 2;
      }
      @media (prefers-reduced-motion: reduce) {
        .browser-tab,
        .browser-tab.is-dragging {
          transition: none !important;
        }
      }
`;
